from typing import List

def findMaxMinValueUsingKElements(shop1: List[int], shop2: List[int], k: int) -> int:
    # dp[j]: 选了 j 个下标时，{shop1 的和: 对应 shop2 的最大和}
    dp = [dict() for _ in range(k + 1)]
    dp[0][0] = 0
    for a, b in zip(shop1, shop2):
        for j in range(k - 1, -1, -1):          # 倒序，保证每个下标最多选一次
            for s1, s2 in list(dp[j].items()):
                nxt = dp[j + 1]
                if nxt.get(s1 + a, float('-inf')) < s2 + b:
                    nxt[s1 + a] = s2 + b
    # ponytail: 状态数受 shop1 的和的取值个数限制，值域很大时需要换思路（如二分答案 + 背包判定）
    return max(min(s1, s2) for s1, s2 in dp[k].items())
